/// <summary>
/// PaffH 17.05.21
/// NDXDataArea.Checked must be set to release to Product 
/// </summary>
public void syncReleaseProductLegalEntity()
{
    NDXDataArea nDXDataArea;
    CompanyInfo companyInfo;
    container conUKs = conNull();
    for (companyInfo = companyInfoFormDataSource.getFirst(true);
        companyInfo;
        companyInfo = companyInfoFormDataSource.getNext())
    {
        nDXDataArea = NDXDataArea::find(companyInfo.DataArea);
        if (nDXDataArea.Checked == NoYes::No)
        {
            conUKs += companyInfo.DataArea;
            companyInfoFormDataSource.markRecord(companyInfo, 0);
        }
    }
    if (conLen(conUKs) > 0)
    {
        NDXDataAreaType::MessageItemIdPrefixSettingMissing(conUKs);
    }

    next syncReleaseProductLegalEntity();
}
